"""Builds handoff/QUEUE_BULK.md: hundreds of small, safe, parallel-friendly quality tasks (one app x one kind of work).
Run: python tools/queue_bulk.py   (deterministic; rerun after apps are added)."""
import json, os, re
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
txt = open(os.path.join(ROOT, "tools/web_public/olympus/apps-list.js"), encoding="utf-8").read()
APPS = [a for a in dict.fromkeys(re.findall(r'"id":\s*"([a-z0-9]+)"', txt)) if a not in ("zenith", "planner")]
KINDS = [
 ("answer", "First-screen answer", "The first screen must answer 'what should I do right now?' in ONE plain sentence at the top (from the already-published data; demo text when missing)."),
 ("states", "Empty / error / offline states", "Every view gets a friendly state for: no data yet, failed fetch, offline. Each says what happened and what the owner can do. Never blank, never a raw error."),
 ("motion", "Micro-animations", "Add 3-5 small, tasteful animations (entrance stagger, number count-up, press feedback, pulse on change). 60 fps on phone, off in reduced motion and LITE."),
 ("copy", "Plain-words pass", "Rewrite every label, tooltip and sentence in 8th-grade words. Every $ next to its R. Eval cards say 'Drawdown left $X of $max loss'. No jargon without a one-line explanation."),
 ("taps", "Tap targets and spacing", "Every control >= 44 px, 8 px+ between controls, nothing under Jarvis's orb corner (bottom-right 80x160), no sideways scroll at 360, 375, 390, 430 px widths."),
 ("lite", "LITE tier polish", "The LITE (low) look must still be beautiful: gradients, glow, simple shapes, no heavy effects. Check `?q=low` and `?q=off` screenshots."),
 ("a11y", "Accessibility pass", "Labels on icon buttons, focus order, 4.5:1 contrast, reduced-motion, big-text toggle, VoiceOver names. Use `olympus/a11y.js`; report anything it cannot fix."),
 ("skeleton", "Loading and first paint", "A beautiful loading state under 300 ms, no layout jump when data arrives, the veil lifts as soon as the first useful frame is ready."),
 ("fixtures", "Demo scenarios", "Add 3 demo scenarios selectable with `?demo=good|bad|empty` (a great day, a losing streak near the floor, nothing yet) so every state can be seen and tested."),
 ("tests", "Test hardening", "Make this app's test robust: dynamic counts (no hard-coded totals), waits instead of fixed sleeps, one quick `--static` part that needs no browser, readable failure messages."),
 ("perf", "Performance trim", "Measure draw calls/triangles/heap with `tests/test_olympus_kit.py`; cut 10-20% without changing the look (instancing, merging, fewer lights, throttle when hidden)."),
 ("share", "Share card", "A 'Share' button that draws a clean 1080x1350 PNG of the app's key numbers on the phone (canvas, nothing sent anywhere) and opens the iOS share sheet."),
 ("themes", "All 7 themes", "Check the app in every OLYMPUS theme (`olympus.theme` key, see `olympus/themes.js`): fix unreadable text, clashing colours, hard-coded colours that ignore the theme."),
 ("feature", "One new money feature", "Invent and build ONE small read-only feature that helps the owner make or protect money (from already-published JSON only). Explain the idea in the PR in 3 lines first; keep it small."),
 ("docs", "Docs and map", "Write/refresh this app's section in `docs/CLAUDE_REFERENCE.md` (what it shows, data it reads, test, how to run) in plain words with the real numbers; add a 30-second 'how to use' card inside the app if missing."),
]
out = ["# Bulk queue: hundreds of small tasks for many ChatGPT / Codex agents at once", "",
 "Generated by `tools/queue_bulk.py` (%d apps x %d kinds = %d tasks). Task id = `<app>-<kind>`. Rules: `handoff/CODEX_RUNBOOK.md` (PARALLEL MODE)." % (len(APPS), len(KINDS), len(APPS) * len(KINDS)), "",
 "How to claim: before you start, run `git ls-remote --heads origin chatgpt/<task-id>`. If a branch already exists, someone has it: skip. Otherwise push your branch immediately (even empty) to claim it.",
 "Do NOT edit this file or `QUEUE.md` (many agents edit in parallel = conflicts). When done, add ONE new file `handoff/done/<task-id>.md` (what changed, PR number, what you could not check).", ""]
for kid, title, body in KINDS:
    out.append(f"## {title} (`<app>-{kid}`)")
    out.append(body)
    out.append("Apps: " + ", ".join(f"`{a}-{kid}`" for a in APPS))
    out.append("")
open(os.path.join(ROOT, "handoff/QUEUE_BULK.md"), "w", encoding="utf-8").write("\n".join(out))
print(len(APPS), "apps x", len(KINDS), "kinds =", len(APPS) * len(KINDS), "tasks")
